---@class GoFishReadyState
local GoFishReadyState = Class("GoFishReadyState", GoFishBaseState)

function GoFishReadyState:__init(view)
    self.TransferTo = view.TransferTo
    for k, v in pairs(view) do
        self[k] = v
    end
    self.handler = Events.AddListener("CanStartAutoFishingReqEnd", Bind(self, self.CanStartAutoFishingReqEnd))
end

function GoFishReadyState:__delete()
    if self.handler then
        Events.RemoveListener("CanStartAutoFishingReqEnd", self.handler)
        self.handler = nil
    end
end

function GoFishReadyState:CanTransfer(target)
    if target == EGoFishState.Casting then
        return true
    else
        return false
    end
end

function GoFishReadyState:OnEnter(params)
    KTool.SetActive(self.controller.gameObject, true)
    self.topGoodsServer:ShowMe()
    self.placeNameServer:ShowMe()
    self.fishingGoodsServer:ShowMe()
    self.autoFishPanelServer:ShowMe()
    self.tipsServer:ShowMe()
    self.roleAnimServer:ChangeRoleStatus(ConstantsFishing.RoleStatus.Idle)
    self.btnLeaveServer:UpdateInfo()
    self.btnLeaveServer:HideMe()
    self.btnFishingGroupServer:ShowMe()
    if FishingUtils.IsAutoing() then
        if self.autoFishPanelServer._isEndAuto then
            self.autoFishPanelServer:ForceStop()
        else
            self.autoFishPanelServer:CanStartAutoFishing()
        end
    else
        self.btnFishingGroupServer:AddClickListener(self, self.OnBtnClick)
    end

    CfUtils.SetActive(self.CommonPrivilegeCardNode, not FishingUtils.IsAutoing())

    self.leftPanelServer:ShowMe()
    self.leftPanelServer:IsBlockClick(false)
    if params then
        self.leftPanelServer:FishResultRoleTalk(params)
    else
        self.leftPanelServer:RefreshRoleTalkIdle()
    end

    CfUtils.SetUISwitchImage(self.ImgFishing, 1)
    CfUtils.SetUISwitchImage(self.TextPullPole, 1)

    CfUtils.SetActive(self.BtnFishNet, true)
end

function GoFishReadyState:CanStartAutoFishingReqEnd(ret)
    local type = ret.type
    local errMsg = ret.errMsg
    if type == 1 then
        self.autoFishPanelServer:StartAutoFishing()
    else
        if not string.isEmpty(errMsg) then GameUtils.Toast(checkString(errMsg)) end
        self.autoFishPanelServer:ForceStop()
        self.btnFishingGroupServer:AddClickListener(self, self.OnBtnClick)
    end
end

function GoFishReadyState:OnBtnClick()
    local canFish, errMsg = self.btnFishingGroupServer:IsCanFishIng()
    if not canFish then
        GameUtils.Toast(checkString(errMsg))
        return
    end

    CfUtils.StartCoroutineWithBlocker(function()
        local params = {
            isAuto = false
        }
        self.TransferTo(EGoFishState.Casting, params)
    end)
end

function GoFishReadyState:Update()
    self.roleAnimServer:OnUpdate()
end

function GoFishReadyState:OnExit()
    self.autoFishPanelServer:HideMe()
    self.btnFishingGroupServer:HideMe()
    self.tipsServer:HideMe()
end

return GoFishReadyState